"use client";
/* Pudding, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Pudding(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("pudding"); }, []);
  return React.createElement("piix-sprite", { "name": "pudding", ...piixAttrs(props) });
}

export default Pudding;
